#[inline]
fn finish_encode_buffer(
    encode_buffer: EncodeBuffer,
    buf: &mut BytesMut,
    uncompression_buf: &mut BytesMut,
    buffer_settings: &BufferSettings,
    max_message_size: &Option<usize>,
    offset: usize,
    compression_encoding: Option<CompressionEncoding>,
) -> Result<(), Status> {
    if compression_encoding.is_some() {
        *uncompression_buf = encode_buffer.into_inner();
    } else {
        *buf = encode_buffer.into_inner();
    }

    finish_encoded_item(
        buf,
        uncompression_buf,
        *buffer_settings,
        *max_message_size,
        offset,
        compression_encoding,
    )
}

#[inline]
fn finish_encoded_item(
    buf: &mut BytesMut,
    uncompression_buf: &mut BytesMut,
    buffer_settings: BufferSettings,
    max_message_size: Option<usize>,
    offset: usize,
    compression_encoding: Option<CompressionEncoding>,
) -> Result<(), Status> {
    if let Some(encoding) = compression_encoding {
        let uncompressed_len = uncompression_buf.len();

        compress(
            CompressionSettings {
                encoding,
                buffer_growth_interval: buffer_settings.buffer_size,
            },
            uncompression_buf,
            buf,
            uncompressed_len,
        )
        .map_err(|err| Status::internal(format!("Error compressing: {err}")))?;
    }

    // now that we know length, we can write the header
    finish_encoding(compression_encoding, max_message_size, &mut buf[offset..])
}
