673:    fn new(work_queue: SharedDsaWorkQueue, source: Bytes, buf: EncodeBuffer) -> Pin<Box<Self>> {
674:        Box::pin(Self {
675:            work_queue,
676:            source,
677:            buf: Some(buf),
678:            dst: std::ptr::null_mut(),
679:            dst_len: 0,
680:            desc: DsaHwDesc::default(),
681:            completion: DsaCompletionRecord::default(),
682:            retry: None,
683:            submitted: false,
684:            completed: false,
685:            _pin: PhantomPinned,
686:        })
687:    }
688:
689:    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Result<EncodeBuffer, Status>> {
690:        let this = self.as_mut().project_mut();
691:
692:        if !*this.submitted {
693:            let len = this.source.len();
694:            let buf = this.buf.as_mut().expect("pending encode buffer available");
695:            let mut dst = buf.as_encode_buf();
696:            // SAFETY: The pending state owns the encode buffer until completion.
697:            // The direct-DMA pointer is retained only while this pending state is
698:            // alive, and the matching commit happens exactly once on success.
699:            let dst_ptr = unsafe { dst.reserve_uninit_slice_for_pending(len) };
700:            touch_pages_for_dsa(this.source.as_ptr(), dst_ptr, len);
701:
702:            let retry = DsaMemmoveRetry::new(this.source.as_ptr(), dst_ptr, len);
703:            submit_retry(this.work_queue, this.desc, this.completion, &retry)?;
704:            *this.retry = Some(retry);
705:            *this.dst = dst_ptr;
706:            *this.dst_len = len;
707:            *this.submitted = true;
708:        }
709:
710:        if this.completion.status() == DsaCompletionStatus::None.as_u8() {
711:            cx.waker().wake_by_ref();
712:            return Poll::Pending;
713:        }
714:
715:        let retry = this.retry.as_mut().expect("pending retry state available");
716:        match retry.handle_completion(*this.completion, &this.work_queue.config.device_path) {
717:            Ok(DsaRetryAction::Complete) => {
718:                *this.completed = true;
719:                let mut buf = this.buf.take().expect("pending encode buffer available");
720:                // SAFETY: DSA completion with success means the descriptor has
721:                // initialized the exact bytes in the reservation made on the
722:                // first poll. This is the single matching commit for that
723:                // reservation.
724:                unsafe {
725:                    buf.as_encode_buf()
726:                        .advance_reserved_uninit_slice(*this.dst_len);
727:                }
728:                Poll::Ready(Ok(buf))
729:            }
730:            Ok(DsaRetryAction::Retry) => {
731:                submit_retry(this.work_queue, this.desc, this.completion, retry)?;
732:                cx.waker().wake_by_ref();
