    type Item = U;
    type Error = Status;
    type Decode = Ready<Result<Option<U>, Status>>;

    fn decode(self: Pin<&mut Self>, buf: DecodeBuf<'_>) -> Result<Self::Decode, Self::Error> {
        let _ = self;
        let item = Message::decode(buf).map_err(from_decode_error)?;

